class SpellScroll {
    constructor(spellName) {
        this.spellName = spellName;
        // TODO: Make 'powerLevel' a private field. Initialize it to 0.
        this.powerLevel = 0; // This should be private
    }

    // TODO: Make 'calculateCost' a private helper method that uses the private 'powerLevel'.
    // Ensure it always returns a number (powerLevel * 10).
    calculateCost() {
        return this.powerLevel * 10;
    }

    getSpellInfo() {
        // TODO: Use the private powerLevel and the new private calculateCost method.
        return `${this.spellName} Scroll (Power: ${this.powerLevel}, Cost: ${this.calculateCost()} gold)`;
    }

    // TODO: Add a public method, e.g., 'setScribedPower', that allows setting the private powerLevel
    // from outside, but only if the level is between 0 and 100 (inclusive).
    // This method should return true on success, false on failure (consistent return contract).
}

class Wizard {
    constructor(name, mana) {
        this.name = name;
        this.mana = mana;
    }

    scribeSpell(scroll, desiredPower) {
        // Cost of scribing is 2 mana per power level.
        const manaCost = desiredPower * 2;
        if (this.mana >= manaCost) {
            // TODO: Do NOT directly access 'scroll.powerLevel'.
            // Instead, use the new public method on the SpellScroll to set its power level.
            // Ensure this method also handles the return contract from the scroll's setter.
            scroll.powerLevel = desiredPower; // This direct access is the problem!

            this.mana -= manaCost;
            console.log(`${this.name} successfully scribed ${scroll.spellName} at power ${desiredPower}.`);
            return true;
        } else {
            console.log(`${this.name} does not have enough mana to scribe ${scroll.spellName} at power ${desiredPower}.`);
            // TODO: Ensure a consistent return contract (e.g., always return true/false).
            return false;
        }
    }
}

