class SpellScroll {
    #powerLevel;
    constructor(spellName) {
        this.spellName = spellName;
        this.#powerLevel = 0;
    }

    #calculateCost() {
        return this.#powerLevel * 10;
    }

    setScribedPower(level) {
        if (level >= 0 && level <= 100) {
            this.#powerLevel = level;
            return true;
        }
        return false;
    }

    getSpellInfo() {
        return `${this.spellName} Scroll (Power: ${this.#powerLevel}, Cost: ${this.#calculateCost()} gold)`;
    }
}

class Wizard {
    constructor(name, mana) {
        this.name = name;
        this.mana = mana;
    }

    scribeSpell(scroll, desiredPower) {
        const manaCost = desiredPower * 2;
        if (this.mana >= manaCost) {
            if (scroll.setScribedPower(desiredPower)) {
                this.mana -= manaCost;
                console.log(`${this.name} successfully scribed ${scroll.spellName} at power ${desiredPower}.`);
                return true;
            } else {
                console.log(`Failed to imbue ${scroll.spellName} due to invalid power level.`);
                return false;
            }
        } else {
            console.log(`${this.name} does not have enough mana to scribe ${scroll.spellName} at power ${desiredPower}.`);
            return false;
        }
    }
}

